<?php require base_path('views/admin/_nav.php'); ?>
<section class="admin-stat-grid"><?php foreach ([['total','Total articles','bi-files'],['sops','SOPs','bi-list-check'],['errors','Errors','bi-exclamation-octagon'],['requests','Requests','bi-inbox'],['published','Published','bi-check-circle'],['drafts','Drafts','bi-pencil'],['review','Under review','bi-hourglass-split']] as [$key,$label,$icon]): ?><a href="/admin/articles?<?= in_array($key,['sops','errors','requests']) ? 'type='.ucfirst(rtrim($key,'s')) : (in_array($key,['published','drafts']) ? 'status='.ucfirst($key) : ($key==='review'?'status=Under+Review':'')) ?>"><i class="bi <?= $icon ?>"></i><strong><?= (int)$stats[$key] ?></strong><span><?= $label ?></span></a><?php endforeach; ?></section>
<div class="admin-columns"><section class="panel"><div class="panel-heading"><h2>Recently updated</h2><a href="/admin/articles">Manage articles</a></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Article</th><th>Status</th><th>Owner</th><th>Updated</th></tr></thead><tbody><?php foreach ($recent as $item): ?><tr><td><a href="/admin/articles/<?= $item['id'] ?>/edit"><strong><?= e($item['title']) ?></strong><small><?= e($item['type']) ?><?= $item['error_code']?' · '.e($item['error_code']):'' ?></small></a></td><td><span class="badge text-bg-light border"><?= e($item['status']) ?></span></td><td><?= e($item['owner_name']??'Unassigned') ?></td><td><?= date('M j',strtotime($item['updated_at'])) ?></td></tr><?php endforeach; ?></tbody></table></div></section><aside class="panel"><div class="panel-heading"><h2>Search signals</h2><a href="/reports">Full report</a></div><div class="signal-list"><?php foreach ($topSearches as $search): ?><div><span><strong><?= e($search['query']) ?></strong><small><?= (int)$search['searches'] ?> searches</small></span><?php if ($search['gaps']): ?><span class="badge text-bg-warning"><?= (int)$search['gaps'] ?> gaps</span><?php endif; ?></div><?php endforeach; ?><?php if (!$topSearches): ?><p class="text-secondary small">No search activity yet.</p><?php endif; ?></div><div class="feedback-summary"><i class="bi bi-hand-thumbs-up"></i><span><strong><?= (int)($feedbackStats['helpful']??0) ?> / <?= (int)($feedbackStats['total']??0) ?></strong><small>helpful responses</small></span></div></aside></div>
